package org.agentos.tests;
import org.json.*;
import java.io.*;
import java.util.*;

/** Exercises isolated native goal/queue/files/voice discovery operations. Never touches existing user records. */
public final class NativeCapabilitiesProbe {
 static JSONObject o(String key,Object value)throws Exception{return new JSONObject().put(key,value);}
 static JSONObject rpc(String method,JSONObject p)throws Exception{return NativeSocketProbe.rpc(method,p);}
 public static void main(String[] args)throws Exception {
  android.os.Looper.prepareMainLooper();JSONObject evidence=new JSONObject();String id=rpc("thread/start",o("cwd","/data/local/agentos/work")).getJSONObject("thread").getString("id");JSONObject thread=o("threadId",id);
  try{rpc("thread/goal/set",o("threadId",id).put("objective","原生接口只读验收目标").put("status","paused").put("origin","user").put("tokenBudget",1000));JSONObject goal=rpc("thread/goal/get",thread);if(!goal.optJSONObject("goal").optString("objective").contains("原生接口"))throw new IOException("Goal mismatch");rpc("thread/goal/clear",o("threadId",id).put("origin","user"));evidence.put("goal","passed");}catch(Exception e){evidence.put("goal",e.getMessage());}
  try{JSONObject active=rpc("turn/start",o("threadId",id).put("input",new JSONArray().put(o("type","text").put("text","请只执行 /system/bin/sleep 15，完成后回复测试完成。"))));Thread.sleep(1500);JSONArray input=new JSONArray().put(o("type","text").put("text","原生队列验收，不开始执行"));JSONObject q=rpc("thread/queue/add",o("threadId",id).put("clientUserMessageId",UUID.randomUUID().toString()).put("input",input));String queued=q.getJSONObject("queuedSubmission").getString("id");JSONObject list=rpc("thread/queue/list",thread);if(list.getJSONArray("data").length()!=1)throw new IOException("Queue mismatch");rpc("thread/queue/update",o("threadId",id).put("queuedSubmissionId",queued).put("input",input));rpc("thread/queue/reorder",o("threadId",id).put("queuedSubmissionIds",new JSONArray().put(queued)));rpc("thread/queue/delete",o("threadId",id).put("queuedSubmissionId",queued));evidence.put("queue","passed");rpc("turn/interrupt",o("threadId",id).put("turnId",active.getJSONObject("turn").getString("id")));}catch(Exception e){evidence.put("queue",e.getMessage());}
  try{String path="/data/local/agentos/work/.native-acceptance-"+UUID.randomUUID()+".txt";String text="原生文件读写验收";rpc("fs/writeFile",o("path",path).put("dataBase64",android.util.Base64.encodeToString(text.getBytes("UTF-8"),android.util.Base64.NO_WRAP)));String content=new String(android.util.Base64.decode(rpc("fs/readFile",o("path",path)).getString("dataBase64"),android.util.Base64.DEFAULT),"UTF-8");if(!text.equals(content))throw new IOException("File mismatch");rpc("fs/remove",o("path",path));evidence.put("filesystem","passed");}catch(Exception e){evidence.put("filesystem",e.getMessage());}
  try{JSONObject voices=rpc("thread/realtime/listVoices",new JSONObject());evidence.put("voiceDirectory",voices.has("voices"));String voiceId=rpc("thread/start",o("cwd","/data/local/agentos/work")).getJSONObject("thread").getString("id");JSONObject voice=rpc("thread/realtime/start",o("threadId",voiceId).put("outputModality","text").put("transport",o("type","websocket")));evidence.put("realtimeRequestAccepted",true);rpc("thread/realtime/appendText",o("threadId",voiceId).put("text","只回复你好，不执行任何操作。"));Thread.sleep(4000);JSONObject state=NativeSocketProbe.exchange(o("op","state").put("threadId",voiceId));evidence.put("realtimeState",state.optJSONObject("realtime"));evidence.put("realtimeServiceUsable",state.optJSONObject("realtime")!=null&&!state.optJSONObject("realtime").optString("event").endsWith("error"));rpc("thread/realtime/stop",o("threadId",voiceId));}catch(Exception e){evidence.put("realtimeStart",e.getMessage());}
  evidence.put("isolatedThreadId",id).put("syntheticResponses",false);
  try(FileOutputStream out=new FileOutputStream("/data/local/tmp/native-capabilities-acceptance.json")){out.write(evidence.toString().getBytes("UTF-8"));}System.out.println(evidence.toString());
 }
}
